create or replace function private.require_platform_admin()returns void language plpgsql stable security definer set search_path=pg_catalog,private as $$begin if not exists(select 1 from private.platform_admins where auth_user_id=auth.uid())then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;end$$;
create or replace function public.create_report(p_subject_type text,p_subject_id uuid,p_reason_code text,p_description text,p_evidence_object_ids uuid[],p_idempotency_key uuid)returns table(report_id uuid,status text)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_player uuid:=public.current_player_id();begin if v_player is null or not exists(select 1 from public.accounts where player_id=v_player and contact_verified_at is not null)then raise exception using errcode='P0001',detail='PLAYER_NOT_VERIFIED';end if;insert into public.reports(reporter_player_id,subject_type,subject_id,reason_code,description)values(v_player,p_subject_type,p_subject_id,p_reason_code,p_description)returning id,public.reports.status::text into report_id,status;insert into public.report_evidence select report_id,id,v_player,now()from private.evidence_objects where id=any(coalesce(p_evidence_object_ids,'{}'))and owner_player_id=v_player;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id)values(auth.uid(),'report.created','report',report_id,p_idempotency_key);return next;end$$;
create or replace function public.review_report(p_report_id uuid,p_expected_version bigint,p_decision text,p_reason text,p_idempotency_key uuid)returns table(report_id uuid,status text,version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$begin perform private.require_platform_admin();update public.reports set status=p_decision::public.report_status,resolution_reason=p_reason,resolved_at=case when p_decision in('actioned','dismissed')then now()end,assigned_admin_id=auth.uid(),version=public.reports.version+1 where id=p_report_id and public.reports.version=p_expected_version returning id,public.reports.status::text,public.reports.version into report_id,status,version;if report_id is null then raise exception using errcode='P0001',detail='STALE_VERSION';end if;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id,after_state)values(auth.uid(),'report.reviewed','report',report_id,p_idempotency_key,jsonb_build_object('decision',status,'reason',p_reason));return next;end$$;
create or replace function public.apply_moderation_action(p_report_id uuid,p_subject_type text,p_subject_id uuid,p_action text,p_reason text,p_expires_at timestamptz,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_id uuid;begin perform private.require_platform_admin();if p_subject_type in('official_result','result_revision')then raise exception using errcode='P0001',detail='USE_DISPUTE_WORKFLOW';end if;insert into public.moderation_actions(report_id,subject_type,subject_id,action_type,reason,expires_at,actor_admin_id,request_id)values(p_report_id,p_subject_type,p_subject_id,p_action,p_reason,p_expires_at,auth.uid(),p_idempotency_key)returning id into v_id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id)values(auth.uid(),'moderation.applied','moderation_action',v_id,p_idempotency_key);return v_id;end$$;
create or replace function public.merge_duplicate_players(p_review_id uuid,p_surviving_player_id uuid,p_reason text,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v public.duplicate_identity_reviews%rowtype;v_alias uuid;begin perform private.require_platform_admin();select*into v from public.duplicate_identity_reviews where id=p_review_id and status in('open','reviewing')for update;if v.id is null or p_surviving_player_id not in(v.candidate_player_a_id,v.candidate_player_b_id)then raise exception using errcode='P0001',detail='INVALID_STATE_TRANSITION';end if;v_alias:=case when p_surviving_player_id=v.candidate_player_a_id then v.candidate_player_b_id else v.candidate_player_a_id end;insert into private.player_identity_aliases values(v_alias,p_surviving_player_id,v.id,now());update public.players set merged_into_player_id=p_surviving_player_id where id=v_alias;update public.duplicate_identity_reviews set status='merged',surviving_player_id=p_surviving_player_id,decision_reason=p_reason,assigned_admin_id=auth.uid(),decided_at=now()where id=v.id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id,after_state)values(auth.uid(),'identity.merged','player',p_surviving_player_id,p_idempotency_key,jsonb_build_object('aliasPlayerId',v_alias,'reason',p_reason));return p_surviving_player_id;end$$;
create or replace function public.adjust_player_trust_score(p_player_id uuid,p_reason_code text,p_delta numeric,p_source_id uuid,p_idempotency_key uuid)returns table(player_id uuid,previous_score numeric,current_score numeric,ledger_entry_id uuid)language plpgsql security definer set search_path=pg_catalog,public,private as $$begin perform private.require_platform_admin();select coalesce((select l.current_score from private.trust_score_ledger l where l.player_id=p_player_id order by created_at desc limit 1),50)into previous_score;current_score:=greatest(0,least(100,previous_score+p_delta));insert into private.trust_score_ledger(player_id,reason_code,delta,previous_score,current_score,source_id,actor_auth_user_id,rule_version,request_id)values(p_player_id,p_reason_code,p_delta,previous_score,current_score,p_source_id,auth.uid(),'trust-v1',p_idempotency_key)returning id into ledger_entry_id;player_id:=p_player_id;return next;end$$;
revoke all on function public.create_report(text,uuid,text,text,uuid[],uuid),public.review_report(uuid,bigint,text,text,uuid),public.apply_moderation_action(uuid,text,uuid,text,text,timestamptz,uuid),public.merge_duplicate_players(uuid,uuid,text,uuid),public.adjust_player_trust_score(uuid,text,numeric,uuid,uuid)from public;grant execute on function public.create_report(text,uuid,text,text,uuid[],uuid),public.review_report(uuid,bigint,text,text,uuid),public.apply_moderation_action(uuid,text,uuid,text,text,timestamptz,uuid),public.merge_duplicate_players(uuid,uuid,text,uuid),public.adjust_player_trust_score(uuid,text,numeric,uuid,uuid)to authenticated;
